VAR
  Overload_Latched : BOOL;
END_VAR

// Overload detection logic
Overload_Timer(IN := (Motor_Current > 51.9) AND Motor_Running, PT := T#3S);

// Latch the fault condition
IF Overload_Timer.Q THEN
    Overload_Latched := TRUE;
    Overload_Alarm := TRUE;
END_IF;

// Reset the fault condition
IF Fault_Reset THEN
    Overload_Latched := FALSE;
    Overload_Alarm := FALSE;
END_IF;

// Stop command logic
Motor_Stop := Overload_Latched;

